/// <summary>
/// MPJ_24248 Pricing Data Extract
/// Track changes related to prices and add entry to Price Change tracking table for later processing
/// </summary>
public class METPriceChangeEventManage
{
}

Method.Source:
    /// <summary>
    /// MPJ_24248 Pricing Data Extract
    /// Process the change 
    /// </summary>
    /// <param name = "_parameters">Container of Parameters</param>
    /// <returns>Container of messages</returns>
    public static container processEvent(container _parameters)
    {
        container   resultCon;

        try
        {
            METPriceChangeType  priceChangeType = conPeek(_parameters, 1);
            Common              common          = conPeek(_parameters, 2);
            SysAppCRUDOperation crud            = conPeek(_parameters, 3);

            METPriceChangeEvent priceChangeEvent = METPriceChangeEventFactory::newFromPriceChangeType(priceChangeType);
            priceChangeEvent.initInstance(common, crud);
            priceChangeEvent.process();
        }
        catch(Exception::CLRError)
        {
            str message = AifUtil::getClrErrorMessage();

            resultCon = [message];
        }
        catch
        {
            int line = infologLine();
            for(int i = 1; i <= line ; i++)
            {
                str message = infolog.text(i);

                resultCon += [message];
            }
        }

        return  resultCon;
    }

    /// <summary>
    /// Result of the trackChange operation
    /// </summary>
    /// <param name = "_result">Result</param>
    public static void callBackResult(AsyncTaskResult _result)
    {
        container result;

        result      = _result.getResult();
        METPriceChangeEventManage::buildResultMessage(result);
    }

    /// <summary>
    /// Result of the trackChange operation
    /// </summary>
    /// <param name = "_result">Result</param>
    public static void buildResultMessage(container _result)
    {
        container   result;
        str         resultStr;

        result      = _result;
        resultstr   = conPeek(result, 1);
 
        if(resultstr)
        {
            SystemNotificationDataContract notification = new SystemNotificationDataContract();
            notification.Users().value(1, curUserId());
            notification.Title("@MET:PriceChangeEvent");
            notification.RuleId("@MET:PriceChangeEventRule");
            notification.Message(resultstr);
            notification.Severity(SystemNotificationSeverity::Error);
            notification.ExpirationDateTime(DateTimeUtil::addHours(DateTimeUtil::utcNow(), 1));

            SystemNotificationsManager::AddSystemNotification(notification);
        }
    }
